import sys

def generate_powers(base, limit):
    res = [1]
    if base == 1:
        return res
    cur = 1
    while cur <= limit // base:
        cur *= base
        res.append(cur)
    return res

def main():
    x, y, l, r = map(int, sys.stdin.readline().split())

    px = generate_powers(x, r)
    py = generate_powers(y, r)

    unlucky = set()
    for a in px:
        for b in py:
            s = a + b
            if s > r:
                continue
            if s >= l:
                unlucky.add(s)

    points = [l - 1] + sorted(unlucky) + [r + 1]

    ans = 0
    for i in range(1, len(points)):
        gap = points[i] - points[i - 1] - 1
        if gap > ans:
            ans = gap

    print(ans)

if __name__ == "__main__":
    main()
